# -*- coding: utf-8 -*-
import json, os, re, sys
from pathlib import Path

ROOT = Path(r'D:/repository')
SKIP = {'.git','node_modules','dist','build','.idea','.vscode','__pycache__','.nuxt','.next','coverage'}
CODE_EXT = {'.vue','.js','.ts','.jsx','.tsx','.mjs','.cjs','.json','.scss','.css','.py','.md'}

# 1) build global basename index once
idx = {}
for dirpath, dirnames, filenames in os.walk(ROOT):
    dirnames[:] = [d for d in dirnames if d not in SKIP and not d.startswith('.')]
    for fn in filenames:
        p = Path(fn)
        if p.suffix.lower() in CODE_EXT:
            idx.setdefault(fn.lower(), []).append(os.path.join(dirpath, fn).replace('\\','/'))

d = json.load(open(r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json', encoding='utf-8'))
out = []
for i, c in enumerate(d['candidates']):
    content = c['content']
    title = content.split('\n')[0].strip()
    # project tag
    m = re.search(r'所属项目[：:]\s*([^\n；;]+)', content)
    proj = m.group(1).strip() if m else ''
    # file paths mentioned (with extension)
    files = re.findall(r'[\w\-./]+\.(?:vue|js|ts|jsx|tsx|mjs|cjs|json|scss|css|py)', content)
    bases = []
    for f in files:
        b = f.split('/')[-1].split('\\')[-1].lower()
        if b and b not in bases:
            bases.append(b)
    hits = {}
    for b in bases:
        paths = idx.get(b, [])
        hits[b] = paths[:4]
    out.append({'n': i+1, 'sha': c['body_sha256_16'], 'title': title, 'proj': proj, 'files': bases, 'hits': hits})

json.dump(out, open(r'C:/Users/Administrator/.dsh/cache/memory-audit/verify_index.json','w',encoding='utf-8'), ensure_ascii=False, indent=1)
print('indexed files:', len(idx))
for o in out:
    print('=== #%d %s | %s | proj=%s' % (o['n'], o['sha'], o['title'][:40], o['proj'][:20]))
    for b, paths in o['hits'].items():
        print('   %-42s -> %s' % (b, ('HIT ' + ' | '.join(paths)) if paths else 'MISS'))

# -*- coding: utf-8 -*-
import json, os, re
from pathlib import Path
ROOT = Path(r'D:/repository')
SKIP = {'.git','node_modules','dist','build','.idea','.vscode','__pycache__','.nuxt','.next','coverage','.dsh'}
CODE_EXT = {'.vue','.js','.ts','.jsx','.tsx','.mjs','.cjs','.scss','.css','.py','.json'}
MAXF = 400000
d = json.load(open(r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json', encoding='utf-8'))
dirs = [p for p in ROOT.iterdir() if p.is_dir()]
def norm(s): return re.sub(r'[^a-z0-9\u4e00-\u9fff]','',s.lower())
def find_proj(content):
    m = re.search(r'所属项目[：:]\s*([^\n；;，,]+)', content)
    cands = []
    if m: cands.append(m.group(1).strip())
    # also project mentions in body
    for kw in re.findall(r'([\u4e00-\u9fffA-Za-z0-9]{2,12}(?:小程序|物管|监测V3|monitor|住房G|住房C|公共收益|门户|H5|V3|V0|G端))', content):
        cands.append(kw)
    for c0 in cands:
        p0 = norm(c0)
        for d0 in dirs:
            dn = norm(d0.name)
            if dn and (dn in p0 or p0 in dn) and len(dn)>=2:
                return d0
    return None
cache = {}
def proj_text(p):
    k=str(p)
    if k in cache: return cache[k]
    buf=[]
    for dp,dns,fns in os.walk(p):
        dns[:]=[x for x in dns if x not in SKIP and not x.startswith('.')]
        for fn in fns:
            if Path(fn).suffix.lower() not in CODE_EXT: continue
            fp=os.path.join(dp,fn)
            try:
                if os.path.getsize(fp)>MAXF: continue
                buf.append(open(fp,encoding='utf-8',errors='ignore').read())
            except Exception: pass
    cache[k]='\n'.join(buf).lower()
    return cache[k]
STOP={'session','source','cursor','extracted','verified','project','none','true','false','undefined','string','object','array','default','return','import','from','const','type','this','that','with','from','data'}
def tokens(content):
    ts=set()
    for t in re.findall(r'`([^`\n]{3,80})`', content):
        for part in re.findall(r'[A-Za-z_][A-Za-z0-9_]{3,}', t):
            if part.lower() not in STOP: ts.add(part.lower())
    for part in re.findall(r'\b[A-Za-z][a-z0-9]+(?:[A-Z][a-z0-9]+)+\b', content):
        if part.lower() not in STOP: ts.add(part.lower())
    for part in re.findall(r'\b[a-z][a-z0-9_]{5,}\b', content):
        if part.lower() not in STOP: ts.add(part.lower())
    # chinese tech terms 3-8 chars
    for part in re.findall(r'[\u4e00-\u9fff]{3,8}', content):
        if part not in ('所属项目','验证证据','涉及文件','来源会话','代码基线','解决方案','问题根因','修复内容','实现要点','验证与归属','问题背景','其他依赖问题','架构约定','注意事项','筛选与查询','关键规则','配置映射','业务现状与建议','触发条件','关键约束','问题原因','变更要点'):
            ts.add(part)
    return list(ts)
out=[]
for i,c in enumerate(d['candidates']):
    content=c['content']; title=content.split('\n')[0].strip()
    p=find_proj(content)
    toks=tokens(content)
    if p:
        txt=proj_text(p)
        hit=[t for t in toks if t in txt]; miss=[t for t in toks if t not in txt]
    else:
        hit=[]; miss=toks
    ratio = len(hit)/len(toks) if toks else 0
    o={'n':i+1,'sha':c['body_sha256_16'],'title':title[:60],'projdir':p.name if p else 'NONE',
       'tot':len(toks),'hit':len(hit),'ratio':round(ratio,2),'miss':sorted(miss)[:14]}
    out.append(o)
json.dump(out,open(r'C:/Users/Administrator/.dsh/cache/memory-audit/verify3.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
# ascii-safe console
for o in out:
    print('#%02d dir=%-14s tok=%2d hit=%2d r=%.2f miss=%s' % (o['n'],o['projdir'][:14],o['tot'],o['hit'],o['ratio'],','.join(x.encode('ascii','ignore').decode() for x in o['miss'][:6])))

